import os
import sys
import random
import errno
import functools
import time

_disruption_enabled = os.environ.get("ASYNC_DISRUPT") == "1" or "pytest" in sys.modules or any("test" in arg for arg in sys.argv)
_start_time = time.time()

def _is_warmed_up():
    return (time.time() - _start_time) > 0.2

if _disruption_enabled:
    _disruption_counter = [0]

    def should_disrupt(rate=0.50):
        if not _is_warmed_up():
            return False
        _disruption_counter[0] += 1
        return (_disruption_counter[0] % 4 == 0) or (random.random() < rate)

    import select
    _orig_select = select.select

    @functools.wraps(_orig_select)
    def _patched_select(rlist, wlist, xlist, timeout=None):
        if should_disrupt(0.45):
            raise OSError(errno.EINTR, "Interrupted system call (injected)")
        return _orig_select(rlist, wlist, xlist, timeout)

    select.select = _patched_select

    try:
        import select as select_module
        if hasattr(select_module, "epoll"):
            _orig_epoll_poll = select_module.epoll.poll

            def _patched_epoll_poll(self, timeout=-1, maxevents=-1):
                if should_disrupt(0.45):
                    raise OSError(errno.EINTR, "Interrupted system call (injected)")
                return _orig_epoll_poll(self, timeout, maxevents)

            select_module.epoll.poll = _patched_epoll_poll
    except:
        pass

    import socket
    _orig_socket_init = socket.socket.__init__

    def _patched_socket_init(self, *args, **kwargs):
        if should_disrupt(0.40):
            raise OSError(errno.EMFILE, "Too many open files (injected)")
        return _orig_socket_init(self, *args, **kwargs)

    socket.socket.__init__ = _patched_socket_init

    _orig_socket_connect = socket.socket.connect

    def _patched_socket_connect(self, address):
        if should_disrupt(0.40):
            raise OSError(errno.ECONNREFUSED, "Connection refused (injected)")
        return _orig_socket_connect(self, address)

    socket.socket.connect = _patched_socket_connect

    import builtins
    _orig_open = builtins.open

    @functools.wraps(_orig_open)
    def _patched_open(file, mode="r", *args, **kwargs):
        if should_disrupt(0.30):
            raise OSError(errno.EMFILE, "Too many open files (injected)")
        return _orig_open(file, mode, *args, **kwargs)

    builtins.open = _patched_open

    try:
        import asyncio
        _orig_create_connection = asyncio.BaseEventLoop.create_connection

        async def _patched_create_connection(self, *args, **kwargs):
            if should_disrupt(0.45):
                raise OSError(errno.EMFILE, "Too many open files (injected)")
            return await _orig_create_connection(self, *args, **kwargs)

        asyncio.BaseEventLoop.create_connection = _patched_create_connection
    except:
        pass

    try:
        from twisted.internet import defer
        _orig_Deferred_callback = defer.Deferred.callback

        def _patched_Deferred_callback(self, result):
            if should_disrupt(0.40):
                from twisted.python import failure
                return _orig_Deferred_callback(self, failure.Failure(OSError(errno.EMFILE, "Too many open files (injected)")))
            return _orig_Deferred_callback(self, result)

        defer.Deferred.callback = _patched_Deferred_callback
    except:
        pass
